create role anon;create role authenticated;create schema auth;create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;create table tenants(id uuid primary key,shop_type text,status text);create table shop_users(auth_id uuid,tenant_id uuid,owner boolean,perms jsonb);create function my_tenant() returns uuid language sql stable security definer as $$select tenant_id from shop_users where auth_id=auth.uid()$$;create function tenant_active() returns boolean language sql stable security definer as $$select exists(select 1 from tenants where id=my_tenant() and status='active')$$;create function has_shop_perm(p text) returns boolean language sql stable security definer as $$select coalesce((select owner or coalesce((perms->>p)::boolean,false) from shop_users where auth_id=auth.uid()),false)$$;create table customers(id text,tenant_id uuid,deleted boolean default false);create table invoices(id text,tenant_id uuid,customer_id text,total numeric,paid numeric);create table payments(id text primary key,tenant_id uuid default my_tenant(),date timestamptz,kind text,party_type text,party_id text,amount numeric,note text,method text,created_by uuid);create table installment_contracts(id text primary key,tenant_id uuid default my_tenant(),data jsonb,deleted boolean default false,updated_at timestamptz default now());insert into tenants values('00000000-0000-0000-0000-000000000010','mobile','active'),('00000000-0000-0000-0000-000000000020','general','active');insert into shop_users values('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000010',true,'{}'),('00000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000020',true,'{}');insert into customers(id,tenant_id) values('c','00000000-0000-0000-0000-000000000010'),('foreign','00000000-0000-0000-0000-000000000020');insert into invoices values('i','00000000-0000-0000-0000-000000000010','c',10000,2000);insert into installment_contracts(id,tenant_id,data) values('ct','00000000-0000-0000-0000-000000000010','{"id":"ct","customerId":"c","invoiceId":"i","invoiceNum":110,"total":8000,"schedule":[{"n":1,"amt":4000,"paidAmt":0},{"n":2,"amt":4000,"paidAmt":0}]}');grant usage on schema public,auth to authenticated,anon;grant execute on all functions in schema public,auth to authenticated;